class Solution {
    public int lowestWithRepeats(int[] readings) {
        int lo = 0, hi = readings.length - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (readings[mid] > readings[hi]) lo = mid + 1;
            else if (readings[mid] < readings[hi]) hi = mid;
            else hi--;
        }
        return readings[lo];
    }
}

